 "content": "def transform(grid):
    """Extend each repeated diagonal color line in its existing direction to the edge."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Find equally-colored diagonal neighbors, then extend the ray from the pair.
    rays = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color:
                    rays.add((color, r2, c2, dr, dc))
    for color, r, c, dr, dc in rays:
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] == bg:
                out[r][c] = color
            r += dr
            c += dc
    return out
